excels.excel:

EXPORT WITH SHEET="供应商往来对账明细表", HEADER=true,
    MAPPING={"a":"供应商","b":"对账单号","c":"我方应付","d":"对方应收","e":"差异","f":"对账结论","g":"对账日期"},
    FORMAT={"c":"#,##0.00","d":"#,##0.00","e":"#,##0.00","g":"yyyy-MM-dd"},
    FORMULAS={
        E2:'C2-D2',E3:'C3-D3',E4:'C4-D4',E5:'C5-D5',E6:'C6-D6',
        C7:'SUM(C2:C6)',D7:'SUM(D2:D6)',E7:'C7-D7'
    },
    STYLE={
        ROW 7:{bold:true,fillPattern:solid_foreground,fillForegroundColor:lightYellow,alignment:right,verticalAlignment:center},
        E3:{color:red,bold:true}
    }
